<script setup lang="ts">
import { onMounted, reactive, ref } from 'vue';import { Plus, Pencil, Trash2 } from 'lucide-vue-next';import { api } from '@/services/api';import { errorMessage } from '@/utils/errors';import { slugify } from '@/utils/format';import type { ArticleCategory } from '@/types/api';import PageHeader from '@/components/PageHeader.vue';import BaseModal from '@/components/BaseModal.vue';import StatusBadge from '@/components/StatusBadge.vue';import ConfirmDialog from '@/components/ConfirmDialog.vue';
const rows=ref<ArticleCategory[]>([]),open=ref(false),saving=ref(false),err=ref(''),editing=ref<ArticleCategory|null>(null),deleteId=ref<number|null>(null);const form=reactive<any>({name:'',slug:'',description:'',is_active:true});async function load(){rows.value=(await api.articleCategories()).data}function create(){editing.value=null;Object.assign(form,{name:'',slug:'',description:'',is_active:true});open.value=true}function edit(x:ArticleCategory){editing.value=x;Object.assign(form,{name:x.name,slug:x.slug,description:x.description||'',is_active:x.is_active});open.value=true}function autoSlug(){if(!editing.value||!form.slug)form.slug=slugify(form.name)}async function save(){saving.value=true;err.value='';try{await api.saveArticleCategory(form,editing.value?.article_category_id);open.value=false;await load()}catch(e){err.value=errorMessage(e)}finally{saving.value=false}}async function remove(){if(deleteId.value){try{await api.deleteArticleCategory(deleteId.value);deleteId.value=null;await load()}catch(e){alert(errorMessage(e))}}}onMounted(load)
</script>
<template><PageHeader title="Chuyên mục bài viết" description="Nhóm nội dung CMS và tạo đường dẫn SEO theo slug."><button class="btn btn-primary" @click="create"><Plus :size="16"/>Thêm chuyên mục</button></PageHeader><section class="card"><div class="table-wrap"><table class="data-table"><thead><tr><th>ID</th><th>Tên</th><th>Slug</th><th>Trạng thái</th><th></th></tr></thead><tbody><tr v-for="x in rows" :key="x.article_category_id"><td>#{{x.article_category_id}}</td><td><strong>{{x.name}}</strong><div class="muted">{{x.description}}</div></td><td>{{x.slug}}</td><td><StatusBadge :value="x.is_active"/></td><td><div class="actions"><button class="btn btn-secondary btn-sm" @click="edit(x)"><Pencil :size="14"/>Sửa</button><button class="btn btn-danger btn-sm" @click="deleteId=x.article_category_id"><Trash2 :size="14"/></button></div></td></tr></tbody></table></div></section><BaseModal :open="open" :title="editing?'Sửa chuyên mục':'Thêm chuyên mục'" @close="open=false"><div v-if="err" class="alert alert-danger">{{err}}</div><div class="form-grid"><label class="field"><span>Tên</span><input v-model="form.name" @blur="autoSlug"/></label><label class="field"><span>Slug</span><input v-model="form.slug"/></label><label class="field full"><span>Mô tả</span><textarea v-model="form.description"/></label><div class="switch-row full"><span>Đang hoạt động</span><label class="switch"><input v-model="form.is_active" type="checkbox"><i/></label></div></div><template #footer><button class="btn btn-secondary" @click="open=false">Hủy</button><button class="btn btn-primary" :disabled="saving" @click="save">Lưu</button></template></BaseModal><ConfirmDialog :open="!!deleteId" title="Xóa chuyên mục" message="Không thể xóa nếu chuyên mục đang được bài viết tham chiếu." @cancel="deleteId=null" @confirm="remove"/></template>
